contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address r) public payable {
        uint256 balBefore = address(c).balance;
        bool reverted;
        c.withdrawAll(r); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted ? address(c).balance == 0 : address(c).balance == balBefore);
    }

    receive() external payable {}
}

